const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();
for (const w of [1280,390]){const p=await b.newPage({viewport:{width:w,height:900}});
p.on('console',m=>console.log('console',m.text()));p.on('pageerror',e=>console.log('err',e.message));
await p.goto('http://127.0.0.1:'+process.env.PORT+'/contact.html');
console.log(w, await p.evaluate(()=>[document.documentElement.scrollWidth, innerWidth]));
await p.screenshot({path:process.env.TMPDIR+'/c'+w+'.png',fullPage:true});}
await b.close()})()
EOF
